function clean(n){if(!n||typeof n!=='object')return n;if(n.type==='VariableDeclaration'&&n.declarations.length===1&&n.declarations[0].id.name==='_rpCleBouton')return null;if(n.type==='IfStatement'&&n.consequent?.expression?.callee?.name==='appliquerTraductionsRP')return null;const call=n.expression?.type==='ChainExpression'?n.expression.expression:n.expression;if(n.type==='ExpressionStatement'&&call?.type==='CallExpression'&&['msg','zone','bouton'].includes(call.callee.object?.name)&&['setAttribute','removeAttribute'].includes(call.callee.property?.name)&&call.arguments[0]?.value==='data-i18n')return null;if(Array.isArray(n))return n.map(clean).filter(x=>x!==null);const o={};for(const [k,v]of Object.entries(n))if(!['start','end','loc','raw'].includes(k))o[k]=clean(v);if(n.type==='FunctionDeclaration'&&n.id.name==='afficherMessageIdentifiants')o.params=o.params.slice(0,1);if(n.type==='CallExpression'&&n.callee.name==='afficherMessageIdentifiants')o.arguments=o.arguments.slice(0,1);const empty=x=>!x||x.type==='BlockStatement'&&!x.body.length;if(n.type==='IfStatement'&&empty(o.consequent)&&empty(o.alternate))return null;return o;}
test('compte : programme entier et français inchangés hors métadonnées de présentation',()=>{
 const p=path.join(root,'outils/audits/I18N-RETOURS-COMPTE-871-preuve.json'),proof=fs.existsSync(p)?JSON.parse(fs.readFileSync(p)):null;
 const sourceFile=f=>proof?execFileSync('git',['show',proof.codeCommit+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}):read(f);const source=sourceFile('creation.js');assert.deepEqual(clean(parse(source)),clean(parse(old('creation.js'))));assert.equal(sourceFile('index.html').replace('creation.js?v=compte-retours-871-','creation.js?v='),old('index.html'));
 const ref=proof?.codeCommit||execFileSync('git',['merge-base','HEAD','origin/main'],{cwd:root,encoding:'utf8'}).trim();assert.equal(execFileSync('git',['diff','--name-only',base,ref,'--','api','migrations','supabase','supabase.js','auth.js','data.js','i18n'],{cwd:root,encoding:'utf8'}),'');
});
function resources(){const c={};c.window=c;vm.createContext(c);vm.runInContext(read('i18n/resources.js'),c);return c.RP_I18N_RESOURCES;}
test('compte : huit traductions existantes complètes dans les neuf langues, aucune copie de catalogue',()=>{
 const cat=resources();for(const lang of ['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'])for(const key of ['errEmail','errPassword','errUnavailable','errSession','errEmailTaken','errGeneric','working','submit']){const text=cat[lang].translation.auth[key];assert.ok(text.trim());if(lang!=='fr')assert.notEqual(text,cat.fr.translation.auth[key]);}
});
async function simulate(mode,before){
 const i=engine.createInstance();await i.init({lng:'fr',fallbackLng:'fr',resources:resources(),interpolation:{escapeValue:false}});const calls=[],elements={};for(const id of ['auth-email','auth-mdp','auth-valider','auth-msg'])elements[id]={id,value:'',textContent:'',style:{display:'none'},attrs:{},setAttribute(k,v){this.attrs[k]=v;},getAttribute(k){return this.attrs[k]??null;},removeAttribute(k){delete this.attrs[k];}};
 elements['auth-email'].value=mode==='email'?'invalid':'fixture@example.invalid';elements['auth-mdp'].value=mode==='password'?'court':'mot-de-passe-fictif';elements['auth-valider'].textContent=i.t('auth.submit');elements['auth-valider'].attrs['data-i18n']='auth.submit';
 const c={i18next:i,document:{getElementById:id=>elements[id],documentElement:{},querySelectorAll:s=>s.includes('placeholder')&&!s.includes(',')?[]:Object.values(elements).filter(e=>e.attrs['data-i18n'])},RP_I18N_LANGUES_SUPPORTEES:['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'],console:{warn(){}},rpAuthAssurerSession:async()=>{calls.push(['session']);if(mode==='throwsSession')throw Error('fixture');return mode==='noSession'?null:{fixture:true};},rpAuthSecuriserCompte:async(...a)=>{calls.push(['secure',...a]);if(mode==='throwsSecure')throw Error('fixture');return mode==='taken'?{ok:false,raison:'email_exists'}:mode==='generic'?{ok:false,raison:'raison libre'}:mode==='null'?null:{ok:true};},goTo:n=>{calls.push(['screen',n]);if(mode==='catch')throw Error('fixture');}};c.window=c;if(mode==='unavailable')delete c.rpAuthSecuriserCompte;vm.createContext(c);vm.runInContext('let IDENTIFIANTS_EN_COURS=false;\n'+selected(before?old('creation.js'):read('creation.js'),['rpMessageIdentifiants','afficherMessageIdentifiants','validerIdentifiants'])+'\n'+selected(read('i18n/i18n-init.js'),['appliquerTraductionsRP'])+'\nwindow.lock=()=>IDENTIFIANTS_EN_COURS;',c);await c.validerIdentifiants();return {calls,locked:c.lock(),message:elements['auth-msg'].textContent,style:{...elements['auth-msg'].style},button:elements['auth-valider'].textContent,disabled:elements['auth-valider'].disabled};
}
test('compte : onze parcours simulés, mêmes appels, verrou, français et navigation que main',async()=>{for(const mode of ['email','password','unavailable','noSession','taken','generic','null','success','catch','throwsSession','throwsSecure'])assert.deepEqual(await simulate(mode,false),await simulate(mode,true),mode);});
